{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))

    by_id = {node.get("id"): node for node in nodes}
    children = {node.get("id"): [] for node in nodes}
    for node in nodes:
        parent = node.get("parent")
        node_id = node.get("id")
        if parent in children:
            children[parent].append(node_id)

    retained = set()

    def retain_with_ancestors(node_id):
        seen = set()
        current = node_id
        while current in by_id and current not in seen:
            seen.add(current)
            retained.add(current)
            current = by_id[current].get("parent")

    for node in nodes:
        if not node.get("removable", False):
            retain_with_ancestors(node.get("id"))

    for symbol in required:
        candidates = [node for node in nodes if node.get("symbol") == symbol]
        if candidates:
            selected = max(candidates, key=lambda node: node.get("utility", 0))
            retain_with_ancestors(selected.get("id"))

    removed = []
    retained_ids = []
    for node in nodes:
        node_id = node.get("id")
        if node_id in retained:
            retained_ids.append(node_id)
        elif node.get("removable", False):
            removed.append(node_id)
        else:
            retain_with_ancestors(node_id)
            retained_ids.append(node_id)

    retained_ids = [node.get("id") for node in nodes if node.get("id") in retained]
    removed = [node.get("id") for node in nodes if node.get("id") not in retained and node.get("removable", False)]
    return {"removed_node_ids": removed, "retained_node_ids": retained_ids}"}
